catalog_script_client.script:
/** 
 * verfiedRoutingPolicy: Init with false, set this to true if the routing policy validation is done
 */

var verfiedRoutingPolicy = false;

function onSubmit() {

    var answer = confirm(getMessage("Are you sure to revoke the selected certificate(s)?"));
    if (!answer)
        return false;

    var gaRoutingPolicy = new GlideAjax("sn_disco_certmgmt.certificateRoutingPolicyAjax");
    gaRoutingPolicy.addParam("sysparm_name", "revokeCertificates");
    gaRoutingPolicy.addParam('sysparm_issued_certificate', g_form.getValue('revoke_certificates'));
    gaRoutingPolicy.addParam('sysparm_certificate_request_type', 'revoke');
    gaRoutingPolicy.addParam('sysparm_reason', g_form.getValue('reason'));
    gaRoutingPolicy.getXML(csrAttributes);

    function csrAttributes(response) {
        var result = response.responseXML.documentElement.getAttribute("answer");
        var routingPolicyObj = JSON.parse(result);
    }
    return true;
}
